          {/capture}
          {=og_include('compose/Group.latte', ['gap' => '4', 'align' => 'baseline', 'justify' => 'between', 'children' => (string) $c_3])|noescape}
          {capture $c_9}
            {foreach og_l(og_where($v_jobs, 'dept', og_get($v_d, ['id']))) as $v_j}
              {capture $c_8}
                {capture $c_6}
                  {capture $c_4}
                    {=og_text(og_get($v_j, ['title']))}
                  {/capture}
